(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['mass','exposure','background'],defaults={mass:55,exposure:1,background:100},get=k=>document.getElementById('C04-'+k);let state={};function update(){const m=+get('mass').value,t=+get('exposure').value,bg=+get('background').value,A=20*m*t,cap=4095-bg,ratio=A<=cap?1:cap/A*(1+Math.log(A/cap));keys.forEach(k=>get(k+'-value').textContent=(+get(k).value).toFixed(1));state={mass:m,exposure:t,background:bg,apparent_mass_ng:m*ratio,ideal_peak_counts:bg+A,recorded_peak_counts:Math.min(4095,bg+A),retained_fraction:ratio};get('result').textContent=(zh?'真实上样量：':'True load: ')+m.toFixed(1)+' ng; '+(zh?'曝光校正后的表观量：':'exposure-corrected apparent load: ')+(m*ratio).toFixed(2)+' ng; '+(zh?'保留积分：':'retained integral: ')+(ratio*100).toFixed(1)+'%';const ymax=Math.max(4500,Math.ceil((bg+A)/1000)*1000),X=x=>80+(x+4)/8*630,Y=y=>290-y/ymax*240;let h='<rect width="760" height="360" fill="#fcfbf7"/><path d="M80 40V290H710" stroke="#61758a" fill="none"/>';for(let j=0;j<=4;j++){let v=ymax*j/4;h+='<text x="70" y="'+(Y(v)+4)+'" text-anchor="end" font-size="12">'+v.toFixed(0)+'</text>';}h+='<line x1="80" x2="710" y1="'+Y(4095)+'" y2="'+Y(4095)+'" stroke="#c49b35" stroke-dasharray="5 4"/>';for(let mode=0;mode<2;mode++){let path='';for(let i=0;i<=160;i++){let x=-4+i*.05,v=bg+A*Math.exp(-x*x/2);if(mode)v=Math.min(4095,v);path+=(i?'L':'M')+X(x).toFixed(2)+' '+Y(v).toFixed(2)+' ';}h+='<path d="'+path+'" fill="none" stroke="'+(mode?'#d35f47':'#167d9a')+'" stroke-width="'+(mode?3:1.8)+'"'+(mode?'':' stroke-dasharray="6 3"')+'/>';}h+='<text x="90" y="24" font-size="13">'+(zh?'中心剖面 / 探测器计数':'Central profile / detector counts')+'</text><text x="395" y="320" text-anchor="middle" font-size="13">'+(zh?'相对中心位置 / 标准差单位':'Position relative to center / standard-deviation units')+'</text><text x="90" y="347" font-size="13" fill="#167d9a">'+(zh?'虚线：理想响应':'Dashed: ideal response')+'</text><text x="400" y="347" font-size="13" fill="#d35f47">'+(zh?'实线：记录的响应':'Solid: recorded response')+'</text>';get('plot').innerHTML=h;}function set(p){keys.forEach(k=>{if(p[k]!==undefined){const e=get(k);e.value=Math.max(+e.min,Math.min(+e.max,+p[k]));}});update();}keys.forEach(k=>get(k).addEventListener('input',update));get('reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};update();})();
